def collect(c):
    sources = []
    data_roots = [c["data_dir"], *c.get("data_dirs", [])]
    for data_dir in data_roots:
        root = Path(data_dir).resolve()
        rows = [{"path": str(p), "label": label,
                 "group": f"{root.name}:{p.relative_to(root)}"}
                for label in ["negative", "positive"]
                for p in sorted((root / label).rglob("*"))
                if p.is_file() and p.suffix.lower() == ".wav"]
        sources.append((root, rows, root.name))
    manifest_paths = [c["manifest_csv"], *c.get("manifest_csvs", [])]
    for manifest_path in manifest_paths:
        if not manifest_path:
            continue
        manifest = Path(manifest_path).resolve()
        with manifest.open(encoding="utf-8-sig", newline="") as f:
            rows = list(csv.DictReader(f))
        sources.append((manifest.parent, rows, manifest.parent.name))
    if not sources:
        raise ValueError("至少需要一个数据目录或 manifest CSV")
    records, seen = [], {}
    for root, rows, source_name in sources:
        positive_rows = [r for r in rows if r.get("label") == "positive"]
        if c["positive_count"] > 0 and positive_rows:
            if c["positive_count"] > len(positive_rows):
                raise ValueError(f"positive_count={c['positive_count']} 超过当前数据源正样本数 {len(positive_rows)}")
            count = c["positive_count"]
        elif c["positive_fraction"] < 1 and positive_rows:
            count = max(1, int(math.floor(len(positive_rows) * c["positive_fraction"])))
        else:
            count = None
        if count is not None and positive_rows:
            selector = np.random.default_rng(c["seed"])
            selected = set(selector.choice(len(positive_rows), size=count, replace=False).tolist())
            positive_index = {id(r): i for i, r in enumerate(positive_rows)}
            rows = [r for r in rows
                    if r.get("label") != "positive"
                    or positive_index[id(r)] in selected]
        for r in rows:
            if r.get("label") not in ["negative", "positive"] or not r.get("path"):
                raise ValueError("manifest 必须有 path,label，标签仅支持 positive/negative")
            path = (root / r["path"]).resolve()
            audio = load_wav(path)
            digest = hashlib.sha256(audio.tobytes()).hexdigest()
            if digest in seen:
                raise ValueError(f"重复 PCM 音频: {path} 与 {seen[digest]}")
            seen[digest] = path
            start = float(r.get("start") or 0)
            end = float(r.get("end") or len(audio) / 16000)
